package com.example.paymentservicefeb25.webhooks;
import com.example.paymentservicefeb25.services.PaymentService; import com.fasterxml.jackson.databind.*; import com.stripe.exception.SignatureVerificationException; import com.stripe.model.Event; import com.stripe.net.Webhook; import org.springframework.beans.factory.annotation.Value; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/payments/webhook") public class StripeWebhookController { private final PaymentService service; private final ObjectMapper mapper; private final String secret; public StripeWebhookController(PaymentService service,ObjectMapper mapper,@Value("${stripe.webhook-secret:}")String secret){this.service=service;this.mapper=mapper;this.secret=secret;} @PostMapping public ResponseEntity<String> handle(@RequestBody String payload,@RequestHeader(value="Stripe-Signature",required=false)String signature)throws Exception{if(secret.isBlank()||signature==null)return ResponseEntity.badRequest().body("Stripe webhook secret/signature is not configured"); Event event;try{event=Webhook.constructEvent(payload,signature,secret);}catch(SignatureVerificationException e){return ResponseEntity.badRequest().body("Invalid Stripe signature");} JsonNode obj=mapper.readTree(payload).path("data").path("object");String t=event.getType();if("checkout.session.completed".equals(t)&&"paid".equalsIgnoreCase(obj.path("payment_status").asText())){Long id=extract(obj);if(id!=null)service.processWebhook(event.getId(),"PaymentSucceeded",id,obj.path("payment_intent").asText(null));}else if("payment_intent.payment_failed".equals(t)){Long id=extract(obj);if(id!=null)service.processWebhook(event.getId(),"PaymentFailed",id,obj.path("id").asText(null));}return ResponseEntity.ok("received");} private Long extract(JsonNode o){String v=o.path("metadata").path("orderId").asText(null);if(v==null||v.isBlank())v=o.path("client_reference_id").asText(null);try{return v==null?null:Long.valueOf(v);}catch(Exception e){return null;}}}
